void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    vec2 center = vec2(0.5);

    // 背景矩形的大小
    vec2 bgRectSize = vec2(0.35, 0.2); // 控制背景矩形的大小
    vec2 rectMin = center - bgRectSize * 0.5;
    vec2 rectMax = center + bgRectSize * 0.5;

    // 检查是否在背景矩形内
    bool inBgRect = all(greaterThanEqual(uv, rectMin)) && 
                   all(lessThanEqual(uv, rectMax));

    // 2D旋转矩阵（绕Z轴）
    float angle = iTime * 1.0;
    mat2 rotation = mat2(
        cos(angle), -sin(angle),
        sin(angle), cos(angle)
    );

    // 将 UV 坐标映射到矩形空间 (0.0 到 1.0)
    vec2 rectUV = (uv - rectMin) / bgRectSize;

    // 对颜色层应用旋转（在矩形空间中）
    vec2 colorUV = rotation * (rectUV - 0.5) + 0.5;

    // 渐变色定义
    vec3 color1 = vec3(0.102, 1.0, 1.0);    // 浅蓝
    vec3 color2 = vec3(0.075, 0.224, 1.0);  // 蓝色
    vec3 color3 = vec3(0.376, 0.102, 1.0);  // 紫色
    vec3 color4 = vec3(0.980, 0.357, 0.733);// 粉色
    vec3 color5 = vec3(1.0, 0.547, 0.102);  // 橙色
    vec3 color6 = vec3(1.0, 0.761, 0.102);  // 黄色

    // 计算渐变色
    vec3 color;
    float t = colorUV.x;
    if (t < 0.2) {
        color = mix(color1, color2, t * 5.0);
    } else if (t < 0.4) {
        color = mix(color2, color3, (t - 0.2) * 5.0);
    } else if (t < 0.6) {
        color = mix(color3, color4, (t - 0.4) * 5.0);
    } else if (t < 0.8) {
        color = mix(color4, color5, (t - 0.6) * 5.0);
    } else {
        color = mix(color5, color6, (t - 0.8) * 5.0);
    }

    // 最终颜色：
    vec3 finalColor = inBgRect ? color : vec3(0.0);

    fragColor = vec4(finalColor, 1.0);
}
